// DESCRIPTION: Multi-hop travel to -178,53,107 west of the death hotspot, checking each 32-block leg with isSafeTarget before moving.
async function travelWestAvoidDeathHotspot(bot) {
    if (bot.interrupt_code) return;
    const destX = -178, destY = 53, destZ = 107;
    if (Math.hypot(destX - (-800), destZ - 500) <= 200) {
        log(bot, 'FAILED: target too close to village; pick another x,z.');
        return;
    }
    for (let leg = 0; leg < 40; leg++) {
        if (bot.interrupt_code) return;
        const p = bot.entity.position;
        const dx = destX - p.x, dz = destZ - p.z, d = Math.hypot(dx, dz);
        if (d <= 4) {
            log(bot, 'Near target -178,53,107.');
            return;
        }
        const step = Math.min(32, d);
        let wx = Math.round(p.x + (dx / d) * step);
        let wz = Math.round(p.z + (dz / d) * step);
        if (!isSafeTarget(bot, wx, wz, 48)) {
            const side = leg % 2 ? 1 : -1;
            wx = Math.round(p.x + (dx / d) * step - (dz / d) * side * 8);
            wz = Math.round(p.z + (dz / d) * step + (dx / d) * side * 8);
            if (!isSafeTarget(bot, wx, wz, 48)) continue;
        }
        const ok = d <= 32
            ? await goToPosition(bot, destX, destY, destZ, 3)
            : await goToPosition(bot, wx, destY, wz, 3);
        if (bot.interrupt_code) return;
        if (!ok) await travelTo(bot, wx, destY, wz, 8);
    }
    if (bot.interrupt_code) return;
    await travelTo(bot, destX, destY, destZ);
}
